
'use strict';
/* NUSAJIWA 0.9 — Artist's Edition. Additive; preserves 0.8 save/events and routes. */
const PREMIUM_EGGS={}; // build injects inline art or asset hrefs
const PREMIUM_WORLD={rimba:'rimba',bara:'bara',rembulan:'rembulan',kabut:'kabut'};
function njColor(hex,factor){
 const c=hex.replace('#','');if(!/^[0-9a-fA-F]{6}$/.test(c))return hex;
 return '#'+[0,2,4].map(i=>Math.max(0,Math.min(255,Math.round(parseInt(c.slice(i,i+2),16)*factor))).toString(16).padStart(2,'0')).join('');
}
const njOldPetSVG=petSVG;
petSVG=function(p,small=false){
 if(!p)return '';
 if(p.phase===0){
  const href=PREMIUM_EGGS[p.species]||PREMIUM_EGGS.komodo;
  if(href)return `<svg viewBox="0 0 360 300" role="img" aria-label="Telur magis ${escapeHTML(SPECIES[p.species].name)}"><image href="${href}" x="75" y="-9" width="210" height="300" preserveAspectRatio="xMidYMid meet"/></svg>`;
 }
 // Keep the proven 0.8 line art, enrich material shading, separate body/underside/rim highlights.
 let s=njOldPetSVG(p,small),d=SPECIES[p.species],base=(p.phase===7?(STONES[p.legend]?.aura||d.base):d.base),dark=d.dark,belly=d.belly;
 const uid='njp'+p.species.replace(/[^a-z]/g,'')+p.phase;
 const defs=`<defs><linearGradient id="${uid}skin" x1=".15" y1="0" x2=".77" y2="1" objectBoundingBox="true"><stop offset="0" stop-color="${njColor(base,1.63)}"/><stop offset=".38" stop-color="${njColor(base,1.15)}"/><stop offset=".72" stop-color="${base}"/><stop offset="1" stop-color="${njColor(base,.58)}"/></linearGradient><linearGradient id="${uid}shadow" x1="0" y1="0" x2=".72" y2="1"><stop stop-color="${njColor(dark,1.3)}"/><stop offset="1" stop-color="${njColor(dark,.68)}"/></linearGradient><radialGradient id="${uid}belly"><stop stop-color="${njColor(belly,1.18)}"/><stop offset="1" stop-color="${njColor(belly,.82)}"/></radialGradient></defs>`;
 s=s.replace(/(<svg[^>]*>)/, '$1'+defs);
 s=s.replaceAll('fill="'+base+'"','fill="url(#'+uid+'skin)"').replaceAll('fill="'+dark+'"','fill="url(#'+uid+'shadow)"').replaceAll('fill="'+belly+'"','fill="url(#'+uid+'belly)"');
 return s;
};
const njPreviousPet=petSVG;
petSVG=function(p,small=false){
 if(!p||p.species!=='komodo'||p.phase===0)return njPreviousPet(p,small);
 const old=p.phase>=6;
 const young=p.phase<=2;
 const legendary=p.phase===7;
 const accent=legendary?(STONES[p.legend]?.aura||'#e2c780'):'#d4bf7e';
 const c=p.phase<4?['#688c67','#87aa75','#33544a']:['#6e977b','#8aab7b','#304e44'];
 const scales=Array.from({length:75},(_,i)=>{const x=108+(i%15)*10.1;const y=134+Math.floor(i/15)*14;const nx=(x-183)/91,ny=(y-165)/56;if(nx*nx+ny*ny>0.86)return '';const r=(i%4)+1.6;return `<ellipse cx="${x}" cy="${y}" rx="${r+1}" ry="${r*.7}" fill="${i%3===0?'#c1c49a':'#244d43'}" opacity="${i%3===0?'.39':'.31'}"/>`;}).join('');
 const tailSpikes=Array.from({length:10},(_,i)=>`<path d="M${55+i*17} ${166+i%2*3} l${7+i%3*2} -${13+(i%3)*4} l7 ${17+(i%3)*4}Z" fill="#24453e" opacity=".88"/>`).join('');
 const foot=(x,y,flip=1)=>`<g transform="translate(${x} ${y}) scale(${flip} 1)"><path d="M-10 -15Q-22 13 -30 30Q-22 47 7 39L29 37Q38 33 29 27L10 23L8 -18Z" fill="url(#njKomodoLeg)" stroke="#2a5147" stroke-width="3"/><path d="M-20 32l-5 12m17-10-2 13m19-12 3 10m11-12 3 8" stroke="#e8d5ad" stroke-width="3" stroke-linecap="round"/><path d="M-20 13Q-8 19 9 14" fill="none" stroke="#b1bd93" stroke-width="3" opacity=".6"/></g>`;
 return `<svg viewBox="0 0 360 300" role="img" aria-label="Ilustrasi Komodo fantasi tahap ${PHASES[p.phase]}">
 <defs><radialGradient id="njKomodoBody" cx=".39" cy=".22" r=".91"><stop stop-color="#b7c7a2"/><stop offset=".28" stop-color="${c[1]}"/><stop offset=".70" stop-color="${c[0]}"/><stop offset="1" stop-color="${c[2]}"/></radialGradient>
 <linearGradient id="njKomodoHead" x1=".06" y1="0" x2=".85" y2="1"><stop stop-color="#b8c7a2"/><stop offset=".5" stop-color="#668d75"/><stop offset="1" stop-color="#355b4f"/></linearGradient>
 <linearGradient id="njKomodoLeg" x1="0" y1="0" x2="1" y2="1"><stop stop-color="#789d7b"/><stop offset="1" stop-color="#244c43"/></linearGradient>
 <linearGradient id="njKomodoTail" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#84aa82"/><stop offset="1" stop-color="#33594c"/></linearGradient>
 <radialGradient id="njKomodoEye"><stop stop-color="#ffcc72"/><stop offset=".7" stop-color="#b87b37"/><stop offset="1" stop-color="#6c442a"/></radialGradient>
 <clipPath id="njKomodoScaleClip"><ellipse cx="177" cy="168" rx="101" ry="57"/></clipPath>
 </defs>
 <g transform="translate(180 151) scale(${young?'.82':old?'1.07':'1'}) translate(-180 -151)">
 ${legendary?`<circle cx="175" cy="155" r="125" fill="none" stroke="${accent}" stroke-width="1.6" stroke-dasharray="6 12" opacity=".6"/><path d="m40 88 8-14 8 14-8 14Z M295 56l7-17 7 17-7 16Z" fill="${accent}" opacity=".85"/>`:''}
 <ellipse cx="185" cy="252" rx="126" ry="15" fill="#021819" opacity=".16"/>
 <path d="M122 167Q94 146 62 151Q35 157 21 188Q22 200 44 201Q67 194 110 212Q143 219 151 196Z" fill="url(#njKomodoTail)" stroke="#244b42" stroke-width="3"/>
 <path d="M27 191Q60 184 89 190" fill="none" stroke="#bed4a7" opacity=".53" stroke-width="2.4"/>
 ${foot(126,199,-1)}${foot(228,204,-1)}
 <ellipse cx="177" cy="167" rx="101" ry="57" fill="url(#njKomodoBody)" stroke="#294e42" stroke-width="4.4"/>
 <path d="M95 173C120 211 192 225 247 189Q214 224 170 220Q113 216 95 173Z" fill="#c4c3a0" opacity=".49"/>
 <g clip-path="url(#njKomodoScaleClip)">${scales}<path d="M99 141Q155 111 204 125" fill="none" stroke="#e0dcab" stroke-width="7" opacity=".29" stroke-linecap="round"/></g>
 ${tailSpikes}
 <path d="M139 115q10-18 18-3l11-12q9-6 13 13l14-17q10-1 12 18l12-13q10 0 12 16l9-7q8 2 8 16" fill="#365d4b" stroke="#214639" stroke-width="2"/>
 ${foot(119,214,1)}${foot(233,208,1)}
 <path d="M225 156Q242 121 272 116Q311 111 326 130Q340 144 331 162Q330 182 302 191Q264 196 237 180Z" fill="url(#njKomodoHead)" stroke="#2a5347" stroke-width="4.5"/>
 <path d="M255 174Q294 181 334 159Q335 185 302 191Q264 196 237 180Z" fill="#c4c59d" opacity=".56"/>
 <path d="M264 128Q289 114 309 128" stroke="#e8e0b5" stroke-width="6" fill="none" opacity=".48" stroke-linecap="round"/>
 <path d="M247 160Q273 179 320 174" stroke="#385b4b" stroke-width="2.2" fill="none" opacity=".78"/>
 <circle cx="281" cy="140" r="14.5" fill="#1a3c39"/><circle cx="281" cy="140" r="10.5" fill="url(#njKomodoEye)"/>
 <ellipse cx="282" cy="140" rx="3.1" ry="8.8" fill="#1b2d2c"/><circle cx="278" cy="136" r="3.1" fill="#fff9db"/>
 <ellipse cx="324" cy="152" rx="3.4" ry="2.7" fill="#244b42"/><circle cx="323.1" cy="151" r=".9" fill="#e5dbb2"/>
 <path d="M253 185q27 10 49 3" fill="none" stroke="#345b4d" stroke-width="3" opacity=".6"/>
 ${Array.from({length:22},(_,i)=>{let x=235+i*4.0,y=160+(i%5)*5;return `<circle cx="${x}" cy="${y}" r="${1+(i%3)}" fill="#b5c5a1" opacity=".37"/>`}).join('')}
 ${old?`<path d="M145 111q18-23 28-4m11-11q18-23 23 6" fill="none" stroke="${accent}" stroke-width="3" opacity=".68"/>`:''}
 </g></svg>`;
};

const njOldScenery=scenery;
scenery=function(key){
 const art=(['komodo','tiger'].includes(key))?'bara':(['kuyang'].includes(key)?'rembulan':(['cendrawasih','maleo','bekantan'].includes(key)?'kabut':'rimba'));
 const dots=Array.from({length:11},(_,i)=>`<i style="--x:${10+(i*23%79)}%;--y:${17+(i*31%66)}%;--delay:-${i*.46}s;--dur:${2.6+(i%4)*.7}s"></i>`).join('');
 return `<div class="scene-bg premium-scene land-${art}" aria-hidden="true"><div class="premium-glimmer">${dots}</div></div>`;
};

const NJ_CARE_ICONS={
 feed:'<path d="M16 7C13 3 9 5 9 9C4 9 3 14 5 20C7 27 12 30 16 26C20 30 25 27 27 20C29 14 28 9 23 9C23 5 19 3 16 7Z"/><path d="M16 8Q16 3 19 2M15 7Q10 2 6 5"/><path d="M12 16l1 1m7-1 1 1M14 22h4"/>',
 clean:'<path d="M16 3C12 10 7 15 7 20A9 9 0 0025 20C25 15 20 10 16 3Z"/><path d="M11 21a5 5 0 005 5"/><circle cx="25" cy="6" r="3"/><circle cx="6" cy="8" r="2"/>',
 play:'<circle cx="16" cy="17" r="11"/><path d="M9 9c10 1 13 11 13 16M6 17c7-5 13-6 21-4M15 6c-1 8-4 14-9 17"/><path d="M17 2l1 3m9 21 3 2"/>',
 sleep:'<path d="M24 23C11 29 3 16 9 7C13 2 17 3 19 3C12 12 16 19 24 23Z"/><path d="M22 4h6l-6 6h6M24 15h5l-5 5h5"/>',
 learn:'<path d="M16 26C11 23 6 24 3 24V7C8 5 12 5 16 8V26ZM16 26C21 23 26 24 29 24V7C24 5 20 5 16 8"/><path d="M7 12l5 1M7 17l5 1M20 13l5-1M20 18l5-1"/>',
 bond:'<path d="M16 28C11 23 4 18 4 11C4 3 12 2 16 9C20 2 28 3 28 11C28 18 21 23 16 28Z"/><path d="M10 12C10 9 12 8 14 9"/>'
};
function njCareIcon(k){return '<svg viewBox="0 0 32 32" aria-hidden="true" width="27" height="27" fill="none" stroke="#f5d99c" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round">'+NJ_CARE_ICONS[k]+'</svg>'}
Object.assign(PREMIUM_EGGS,{komodo:"data:image/png;base64,",tiger:"data:image/png;base64,",cendrawasih:"data:image/png;base64,",lembuswana:"data:image/png;base64,",kuyang:"data:image/png;base64,",anoa:"data:image/png;base64,",maleo:"data:image/png;base64,",bekantan:"data:image/png;base64,"});

// Home contains fully playable care but the now-redundant small billboard buttons are
// grouped in a single in-world navigation ribbon to restore composition / legibility.
const njPreviousHome=home;
home=function(){
 let s=njPreviousHome();
 const shortcuts='<div class="premium-activities" aria-label="Aktivitas petualangan"><button data-river06="open"><span>◈</span>Sungai Cahaya</button><button data-living="open"><span>❀</span>Taman Jiwa</button><button data-story="journal"><span>⌘</span>Kitab Penjaga</button><button data-trail08="open"><span>✦</span>Jejakku</button></div>';
 s=s.replace('<div class="home-bottom">','<div class="home-bottom">'+shortcuts);
 for(const [key,emoji] of [['feed','🍉'],['clean','🫧'],['play','🪀'],['sleep','🌙'],['learn','📚'],['bond','♡']])s=s.replace('<span class="tool-glyph">'+emoji+'</span>','<span class="tool-glyph">'+njCareIcon(key)+'</span>');
 s=s.replace('<div class="home-content"><div><div class="chapter-kicker">','<div class="home-content"><div class="scene-heading"><div class="chapter-kicker">');
 return s;
};
// Deliberately keep the six existing choices and save compatibility. No dashboard at start.
starterModal=function(){
 const ids=['komodo','maleo','anoa','lembuswana','bekantan','kuyang'];
 const eggCards=ids.map(id=>{const data=SPECIES[id];return `<button class="starter" data-action="starter-choose" data-species="${id}" aria-label="Mulai dengan telur ${escapeHTML(data.name)}"><small class="starter-kind">${data.type==='fauna'?'Fauna':'Cerita rakyat'}</small>${creatureView(virtualPet(id,0))}<b>${escapeHTML(data.name)}</b><small>${escapeHTML(data.origin)}</small></button>`;}).join('');
 showModal(`<div class="premium-starter"><div class="starter-crest">✧</div><div class="chapter-kicker">PROLOG · ENAM JIWA NUSANTARA</div><h2>Setiap Jiwa Punya Legenda</h2><p class="starter-intro">Pilih satu telur untuk memulai kisahmu. Rawat, jelajahi pulau-pulau, dan temukan delapan fase kehidupan hingga wujud Legend.</p><div class="starter-list">${eggCards}</div><p class="starter-disclaimer">Fauna asli, mitologi dan folklor disajikan secara terpisah di Kodex. Evolusi adalah mekanik fantasi, bukan fakta biologis atau klaim tradisi.</p></div>`,true);
};
// Low-motion adaptation on less powerful devices, keeping game functionality intact.
let njQuality='auto';
try{njQuality=localStorage.getItem('nusajiwa-render-quality')||'auto'}catch(e){}
function njApplyQuality(){const low=njQuality==='hemat'||(njQuality==='auto'&&(navigator.deviceMemory&&navigator.deviceMemory<3));document.body.classList.toggle('nj-economy',!!low)}
njApplyQuality();
const njOldSettings=settingsModal;
settingsModal=function(){
 njOldSettings();
 const pane=document.querySelector('.modal-pane');if(!pane)return;
 const extra=`<div style="margin:17px auto 6px;text-align:left;max-width:420px;border-top:1px solid #eac98b51;padding-top:14px"><b style="color:#f6d99d">Kualitas visual</b><p style="font-size:12px;color:#d7cdb8;margin:5px 0 8px">Pilih detail animasi sesuai kemampuan perangkat.</p><select id="njRenderQuality" aria-label="Kualitas visual" style="display:block;width:100%;padding:12px;border-radius:12px;background:#0c3040;color:#f8e5c0;border:1px solid #e8c48e88"><option value="auto" ${njQuality==='auto'?'selected':''}>Otomatis · disarankan</option><option value="tinggi" ${njQuality==='tinggi'?'selected':''}>Tinggi · animasi penuh</option><option value="hemat" ${njQuality==='hemat'?'selected':''}>Hemat · animasi ringan</option></select></div><p style="font-size:10px;color:#c7c8c1;margin-top:12px">NUSAJIWA Living World 1.1 · Beta playable. Ilustrasi dan suara masih terus dikembangkan.</p>`;
 pane.querySelector('.modal-disclaimer')?.replaceChildren(document.createTextNode('NUSAJIWA Living World 1.1 · progres hanya tersimpan di browser ini. Cadangkan melalui Ekspor Save.'));
 pane.insertAdjacentHTML('beforeend',extra);
};
document.addEventListener('change',ev=>{if(ev.target?.id==='njRenderQuality'){njQuality=ev.target.value;try{localStorage.setItem('nusajiwa-render-quality',njQuality)}catch(e){};njApplyQuality();toast('Kualitas visual diperbarui.')}});
// Replace old-version strings in visible settings without changing settings behavior.
(function(){document.title='NUSAJIWA — The Living Legends | Living World 1.1';document.querySelector('meta[name="theme-color"]')?.setAttribute('content','#081d27');})();
render();if(!state.pets.length)starterModal();

